9	function CreateCompanyLogo($CompanyName, $Path_To_Root, $CompanyDir) {
10		if (extension_loaded('gd')) {
11			// generate an image, based on company name
12	
13			$Font = 3;
14	
15			$im = imagecreatefrompng($Path_To_Root . '/images/logo_background.png');
16			imagealphablending($im, false);
17	
18			//$BackgroundColour = imagecolorallocate($im, 119, 119, 119); // #777777, same as default color theme
19			$TextColour = imagecolorallocate($im, 255, 255, 255);
20	
21			$fw = imagefontwidth($Font);
22			$fh = imagefontheight($Font);
23			$TextWidth = $fw * mb_strlen($CompanyName);
24			$px = (imagesx($im) - $TextWidth) / 2;
25			$py = (imagesy($im) - ($fh)) / 2;
26			//imagefill($im, 0, 0, $BackgroundColour);
27			imagestring($im, $Font, (int)$px, (int)$py, $CompanyName, $TextColour);
28	
29			imagesavealpha($im, true);
30	
31			$Result = true;
32			if (!imagepng($im, $CompanyDir . '/logo.png')) {
33				$Result = copy($Path_To_Root . '/images/default_logo.jpg', $CompanyDir . '/logo.jpg');
34			}
35	
36		} else {
37			$Result = copy($Path_To_Root . '/images/default_logo.jpg', $CompanyDir . '/logo.jpg');
38		}
39	
40		if ($Result) {
41			echo '<div class="success">' . __('A default company logo has been generated') . '</div>';
42		} else {
43			echo '<div class="warning">' . __('Failed generating default company logo.') . '</div>';
44		}
45		flush();
46	
47		return $Result;
48	}
