55	function SaveUploadedCompanyLogo($DatabaseName, $Path_To_Root)
56	{
57		/* Upload logo file */
58		$UploadOK = 1;
59	
60		$TargetDir = $Path_To_Root . '/companies/' . $DatabaseName . '/';
61		$TargetFile = $TargetDir . basename($_FILES["LogoFile"]["name"]);
62		$ImageFileType = strtolower(pathinfo($TargetFile, PATHINFO_EXTENSION));
63	
64		// Check if image file is an actual image or fake image
65		if (isset($_POST["install"])) {
66			$check = getimagesize($_FILES["LogoFile"]["tmp_name"]);
67			if ($check !== false) {
68				$UploadOK = 1;
69			} else {
70				echo '<div class="warning">' . __('Logo file is not an image.') . '</div>';
71				$UploadOK = 0;
72			}
73		}
74	
75		// Check if file already exists
76		if (file_exists($TargetFile)) {
77			echo '<div class="warning">' . __('Sorry, logo file already exists.') . '</div>';
78			$UploadOK = 0;
79		}
80	
81		// Check file size
82		if ($_FILES["LogoFile"]["size"] > 500000) {
83			echo '<div class="warning">' . __('Sorry, your logo file is too large.') . '</div>';
84			$UploadOK = 0;
85		}
86	
87		// Allow certain file formats
88		if ($ImageFileType != "jpg" && $ImageFileType != "png" && $ImageFileType != "jpeg" && $ImageFileType != "gif" ) {
89			echo '<div class="warning">' . __('Sorry, only JPG, JPEG, PNG & GIF logo files are allowed.') . '</div>';
90			$UploadOK = 0;
91		}
92	
93		// Check if $UploadOK is set to 0 by an error
94		if ($UploadOK == 0) {
95			echo '<div class="warning">' . __('Sorry, your logo file was not uploaded.') . '</div>';
96		} else {
97			// if everything is ok, try to upload file
98			if (move_uploaded_file($_FILES["LogoFile"]["tmp_name"], $TargetFile)) {
99				echo '<div class="success">' . __('Your logo has been successfully uploaded') . '</div>';
100			} else {
101				echo '<div class="warning">' . __('Your logo could not be uploaded. You must copy this to your companies directory later.') . '</div>';
102			}
103		}
104		flush();
105	
106		return (bool)$UploadOK;
107	}
