112	function 	CreateDataBase($HostName, $UserName, $Password, $DataBaseName, $DBPort, $DBType, $Path_To_Root) {
113	
114		// avoid exceptions being thrown on query errors
115		mysqli_report(MYSQLI_REPORT_ERROR);
116	
117		$DB = @mysqli_connect($HostName, $UserName, $Password, null, $DBPort);
118		if (!$DB) {
119			echo '<div class="error">' . __('Unable to connect to the database to create the schema.') . '</div>';
120			flush();
121			return false;
122		}
123	
124		$Errors = [];
125	
126		/// @todo move this to a shared function (eg. in UpgradeDB_$DBType.php)
127		/// @todo allow to pick/suggest a preferred charset - possibly leave the choice hidden in the installer, so that
128		///       end users do not get confused, but allow the test suite to force the code path which uses utf8mb3
129		$ListCharsetsSQL = "SHOW COLLATION WHERE Charset = 'utf8mb4'";
130		$ListCharsetsResult = @mysqli_query($DB, $ListCharsetsSQL);
131		if ($ListCharsetsResult) {
132			$Rows = mysqli_num_rows($ListCharsetsResult);
133		} else {
134			echo '<div class="warning">' . __('Failed to check for the available database character sets.') . '</div>';
135			$Rows = 0;
136		}
137	
138		if ($Rows > 0) {
139			$_SESSION['Installer']['DBCharset'] = 'utf8mb4';
140		} else {
141			// NB: utf8 is an alias for utf8mb3, up to Mysql < 8.4, and mariadb < 10.6.1.
142			// After that, it becomes an alias for utf8mb4.
143			// A great win for BC! ;-)
144			// Ideally, the value we pick here should be an utf8 encoding supported by all db-versions/php-versions.
145			// The string 'utf8mb3' is a good candidate, but it was tested on both mysql 8.3 and mariadb 10.5, and it raised
146			// php warnings in both cases :-(
147			// Using 'utf8' instead worked, and got us a 3-bytes charset (tested with `mysqli_get_charset($DB)`).
148			// So be it.
149			// Final note: both mariadb and mysql support utf8mb4 since rev 5.5, which is less-or-equal to the minimum
150			// DB version we support. So this whole block (and the above test) could in fact be removed...
151			$_SESSION['Installer']['DBCharset'] = 'utf8';
152		}
153	
154		if (!mysqli_set_charset($DB, $_SESSION['Installer']['DBCharset'])) {
155			echo '<div class="warning">' . __('Failed setting the database connection character set to') . ' ' . htmlspecialchars($_SESSION['Installer']['DBCharset']) . '</div>';
156		}
157	
158		// gg: we only use this db connection for creating the database, as we use separate one for creating tables etc.
159		//     So this seems useless/overkill
160		//$Result = @mysqli_query($DB, 'SET SQL_MODE=""');
161		//$Result = @mysqli_query($DB, 'SET SESSION SQL_MODE=""');
162	
163		/// @todo move checking for permissions and for existing tables into UpgradeDB_$DBType.php, to give it a chance
164		///       at being db-agnostic
165	
166		$DBExistsSql = "SELECT SCHEMA_NAME FROM information_schema.SCHEMATA WHERE SCHEMA_NAME = '" . mysqli_real_escape_string($DB, $DataBaseName) . "'";
167		$DBExistsResult = @mysqli_query($DB, $DBExistsSql);
168		if ($DBExistsResult) {
169			$Rows = mysqli_num_rows($DBExistsResult);
170		} else {
171			echo '<div class="warning">' . __('Failed to check for the presence of the database schema.') . '</div>';
172			$Rows = 0;
173		}
174	
175		// this query is not failsafe (it does not work on every db type) - it is just as good not to check permissions and just try to create the db...
176		//$PrivilegesSql = "SELECT * FROM information_schema.USER_PRIVILEGES WHERE GRANTEE=" . '"' . "'" . mysqli_real_escape_string($DB, $UserName) . "'@'" . mysqli_real_escape_string($DB, $HostName) . "'" . '"' . " AND PRIVILEGE_TYPE='CREATE'";
177		//$PrivilegesResult = @mysqli_query($DB, $PrivilegesSql);
178		//$Privileges = @mysqli_num_rows($PrivilegesResult);
179	
180		/// @todo exit with errors if any of the above failed?
181	
182		if ($Rows == 0) { /* Then the database does not exist */
183			//if ($Privileges == 0) {
184			//	$Errors[] = __('The database does not exist, and this database user does not have privileges to create it');
185			//} else { /* Then we can create the database */
186				$SQL = "CREATE DATABASE " . $DataBaseName . " CHARACTER SET = " . $_SESSION['Installer']['DBCharset'];
187				if (!@mysqli_query($DB, $SQL)) {
188					$Errors[] = __('Failed creating the database');
189				}
190			//}
191		} else {
192	
193			/* Need to make sure NO data is removed from the existing DB */
194	
195			$SQL = "SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA = '" . $DataBaseName . "'";
196			if (!($Result = @mysqli_query($DB, $SQL))) {
197				$Errors[] = __('Failed enumerating existing database tables');
198			} else {
199				// only check tables which we will recreate
200				$Rows = @mysqli_fetch_all($Result, MYSQLI_ASSOC);
201				$ExistingTablesNum = count($Rows);
202				$TableNames = array();
203				foreach (glob($Path_To_Root . '/install/sql/tables/*.sql') as $FileName) {
204					$SQLScriptFile = file_get_contents($FileName);
205					if (preg_match('/^CREATE +TABLE +`?([^ (`]+)`?/', $SQLScriptFile, $matches)) {
206						$TableNames[] = str_replace('`', '', $matches[1]);
207					}
208				}
209				foreach($Rows as $i => $Row) {
210					if (!in_array($Row['TABLE_NAME'], $TableNames)) {
211						unset($Rows[$i]);
212					}
213				}
214				if (count($Rows)) {
215					$Errors[] = __('Would overwrite' . ' ' . count($Rows) . ' ' . 'existing database tables');
216				} else {
217					if ($ExistingTablesNum > 0) {
218						echo '<div class="warning">' . __('Found') . ' ' . $ExistingTablesNum . ' ' . __('unrelated tables in the existing schema') . '</div>';
219					}
220				}
221			}
222		}
223	
224		if ($Errors) {
225			echo '<div class="error">' . __('Unable to create the database schema.') . '</div>';
226	
227			// display the errors
228			echo '<div class="error">';
229			foreach ($Errors as $error) {
230				echo '<p>' . htmlspecialchars($error) . "</p>\n";
231			}
232			echo '</div>';
233	
234			return false;
235		}
236	
237		return true;
238	}
