300	function CreateTables($Path_To_Root, $DBType) {
301		$DBErrors = 0;
302		foreach (glob($Path_To_Root . '/install/sql/tables/*.sql') as $FileName) {
303			$SQLScriptFile = file_get_contents($FileName);
304	
305			if ($DBType == 'mariadb') {
306				// mariadb 5.5 chokes on STORED
307				$SQLScriptFile = preg_replace('/([) ])STORED([, \n])/', ' $1PERSISTENT$2', $SQLScriptFile);
308			}
309	
310			if ($_SESSION['Installer']['DBCharset'] != 'utf8mb4') {
311				$SQLScriptFile = preg_replace('/ CHARSET *= *utf8mb4/', ' CHARSET = utf8mb3', $SQLScriptFile);
312			}
313	
314			// we disable FKs for each script, in case the previous script re-enabled them
315			/// @todo do we need to disable FKs while creating tables and inserting no data?
316			DB_IgnoreForeignKeys();
317			// avoid the standard error-handling kicking in
318			$Result = DB_query($SQLScriptFile, '', '', false, false);
319			$DBErrors += DB_error_no($Result);
320		}
321		DB_ReinstateForeignKeys();
322		if ($DBErrors > 0) {
323			echo '<div class="error">' . __('Database tables could not be created') . '</div>';
324		} else {
325			echo '<div class="success">' . __('All database tables have been created') . '</div>';
326		}
327		flush();
328	
329		return ($DBErrors == 0);
330	}
