680	function PopulateSQLDataBySQLFile($File, $DBType) {
681		$SQLScriptFile = file($File);
682		$ScriptFileEntries = sizeof($SQLScriptFile);
683	
684		$Errors = 0;
685		$SQL = '';
686		$InAFunction = false;
687		for ($i = 1; $i <= $ScriptFileEntries; $i++) {
688	
689			$SQLScriptFile[$i - 1] = trim($SQLScriptFile[$i - 1]);
690	
691	//		if (mb_substr($SQLScriptFile[$i - 1], 0 ,2) != '--') {
692	
693			/// @todo ignore lines that start with `--` or USE or /* or CREATE DATABASE
694	
695			$SQL.= ' ' . $SQLScriptFile[$i - 1];
696			// check if this line kicks off a function definition - pg chokes otherwise
697			/// @todo we can disable this filter if on mysql/mariadb
698			/// @todo use a regexp
699			if (!$InAFunction && mb_substr($SQLScriptFile[$i - 1], 0, 15) == 'CREATE FUNCTION') {
700				$InAFunction = true;
701			}
702			// check if this line completes a function definition - pg chokes otherwise
703			/// @todo use a regexp
704			if ($InAFunction && mb_substr($SQLScriptFile[$i - 1], 0, 8) == 'LANGUAGE') {
705				$InAFunction = false;
706			}
707			/// @todo run last statement found even if not not comma terminated
708			if (mb_strpos($SQLScriptFile[$i - 1], ';') > 0 and !$InAFunction) {
709				// Database created above with correct name.
710				$Result = DB_query($SQL, '', '', false, false);
711				if (DB_error_no() != 0) {
712					$Errors++;
713				}
714				$SQL = '';
715			}
716			flush();
717	//		}
718	
719		} //end of for loop around the lines of the sql script
720	
721		return ($Errors == 0);
722	}
