752	function CreateConfigFile($Path_To_Root, $configArray, $timezone) {
753		// The config files are in the main directory
754		$SampleConfigFile = $Path_To_Root . '/config.distrib.php';
755		$NewConfigFile = $Path_To_Root . '/config.php';
756	
757		// Read the content of the sample config file
758		if (!file_exists($SampleConfigFile)) {
759			echo '<div class="error">' . __('The sample configuration file does not exist.') . '</div>';
760			return false;
761		}
762	
763		// Open the sample file for reading and create the new config file for writing
764		$SampleHandle = fopen($SampleConfigFile, 'r');
765		$NewLines = [];
766	
767		if ($SampleHandle) {
768			while (($Line = fgets($SampleHandle)) !== false) {
769				// Check if the line is commented (starting with //, #, or within /* */)
770				$isComment = preg_match('/^\s*(\/\/|#|\/\*|\*\/)/', $Line);
771	
772				// Skip replacements on comment lines, otherwise process a config line.
773				if (!$isComment) {
774					// Loop Installer Data
775					foreach ($configArray as $key => $Value) {
776						// if (strpos($Line, $key) !== false) {
777						if (preg_match('/\$\b' . preg_quote($key, '/') . '\b/', $Line)) {
778							$NewValue = addslashes($Value);
779							$Line = "\$$key = '$NewValue';\n";
780							unset($configArray[$key]);
781						}
782					}
783					// Replace date_default_timezone_set
784					if (strpos($Line, 'date_default_timezone_set') !== false) {
785						$NewValue = addslashes($timezone);
786						$Line = "date_default_timezone_set('".$NewValue."');\n";
787					}
788				}
789				// Append the line to the new content
790				$NewLines[] = $Line;
791			}
792	
793			fclose($SampleHandle);
794		} else {
795			echo '<div class="error">' . __('Unable to read the sample configuration file.') . '</div>';
796			return false;
797		}
798	
799		/// @todo allow more flexibility? Check if config.bak.php does not exist, rename the current config file and go on
800	
801		if (file_exists($NewConfigFile)) {
802			echo '<div class="error">' . __('The configuration file exists and has not been overwritten') . ' ' . $NewConfigFile . '</div>';
803			flush();
804			$Result = true;
805	
806		} else {
807			// Write the updated content to the new config file
808			$NewConfigContent = implode($NewLines);
809			$Result = file_put_contents($NewConfigFile, $NewConfigContent);
810	
811			if ($Result) {
812				echo '<div class="success">' . __('The config.php file has been created based on your settings') . '</div>';
813			} else {
814				echo '<div class="error">' . __('Cannot write to the configuration file') . ' ' . $NewConfigFile . '</div>';
815			}
816			flush();
817			$Result = true;
818		}
819		return $Result;
820	}
