1	<?php
2	
3	/* Shows the local manual content if available, else shows the manual content in en-GB. */
4	/* This program is under the GNU General Public License, last version. */
5	/* This creative work is under the CC BY-NC-SA, later version. */
6	
7	/*
8	This table of contents allows the choice to display one section or select multiple sections to format for print.
9	Selecting multiple sections is for printing.
10	The outline of the Table of Contents is contained in the 'ManualOutline.php' file that can be easily translated.
11	The individual topics in the manual are in straight html files that are called along with the header and foot from here.
12	Each function in webERP can initialise a $ViewTopic and $Bookmark variable, prior to including the header.php file.
13	This will display the specified topic and bookmark if it exists when the user clicks on the Manual link in the webERP main menu.
14	In this way the help can be easily broken into sections for online context-sensitive help.
15	Comments beginning with Help Begin and Help End denote the beginning and end of a section that goes into the online help.
16	What section is named after Help Begin: and there can be multiple sections separated with a comma.
17	*/
18	
19	$PageSecurity = 0;
20	
21	// Set the language to show the manual:
22	/*
23	session_start();
24	$Language = $_SESSION['Language'];
25	if (isset($_GET['Language'])) {// Set an other language for manual.
26		$Language = $_GET['Language'];
27	}
28	*/
29	require(__DIR__ . '/includes/session.php');
30	
31	$Title = __('webERP Manual');
32	
33	// Set the Cascading Style Sheet for the manual:
34	$ManualStyle = 'locale/' . $Language . '/Manual/css/manual.css';
35	if (!file_exists($ManualStyle)) { // If locale ccs not exist, use doc/Manual/css/manual.css. Each language can have its own css.
36		$ManualStyle = 'doc/Manual/css/manual.css';
37	}
38	// Set the the outline of the webERP manual:
39	$ManualOutline = 'locale/' . $Language . '/Manual/ManualOutline.php';
40	if (!file_exists($ManualOutline)) { // If locale outline not exist, use doc/Manual/ManualOutline.php. Each language can have its own outline.
41		$ManualOutline = 'doc/Manual/ManualOutline.php';
42	}
43	
44	ob_start();
45	
46	// Output the header part:
47	$ManualHeader = 'locale/' . $Language . '/Manual/ManualHeader.html';
48	if (file_exists($ManualHeader)) { // Use locale ManualHeader.html if exists. Each language can have its own page header.
49		include($ManualHeader);
50	} else {// Default page header:
51		echo '<!DOCTYPE html>
52		<html lang="', str_replace('_', '-', substr($Language, 0, 5)), '">
53		<head>
54		  <title>', $Title, '</title>
55		  <meta http-equiv="Content-Type" content="text/html;charset=utf-8">
56		  <link rel="stylesheet" type="text/css" href="', $ManualStyle, '" />
57		</head>
58		<body>
59			<div id="pagetitle">', $Title, '</div>
60			<div class="right">
61				<a id="top">&#160;</a><a class="minitext" href="', htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8'), '">☜ ', __('Table of Contents'), '</a><br />
62				<a class="minitext" href="#bottom">⬇ ', __('Go to Bottom'), '</a>
63			</div>';
64	}
65	
66	include($ManualOutline);
67	$_GET['Bookmark'] = $_GET['Bookmark'] ?? '';
68	$_GET['ViewTopic'] = $_GET['ViewTopic'] ?? '';
69	
70	//all sections of manual listed here
71	if (((!isset($_POST['Submit'])) and (empty($_GET['ViewTopic']))) || ((isset($_POST['Submit'])) and (isset($_POST['SelectTableOfContents'])))) {
72		echo '<form action="', htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8'), '" method="post">';
73		// if not submittws then coming into manual to look at TOC
74		// if SelectTableOfContents set then user wants it displayed
75		if (!isset($_POST['Submit'])) {
76			echo '<p>', __('Click on a link to view a page'), '</p>';
77		}
78		echo '<h1>';
79		echo __('Table of Contents'), '</h1>';
80		$j = 0;
81		foreach($TOC_Array['TableOfContents'] as $Title => $SubLinks) {
82			$Name = 'Select' . $Title;
83			echo '<ul>
84				<li class="toc"';
85			// List topic title:
86			if (!isset($_POST['Submit'])) {
87				echo ' style="list-style-type:none;">';
88			}
89			echo '<a href="', htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8'), '?ViewTopic=', $Title, '">', $SubLinks[0], '</a></li>';
90			// List topic content:
91			if (count($SubLinks) > 1) {
92				echo '<ul>';
93				foreach($SubLinks as $k => $SubName) {
94					if ($k == 0) {// Skip first array element $SubLinks[0].
95						continue;
96					}
97					echo '<li>', $SubName, '</li>';
98				}
99				echo '</ul>';
100			}
101	
102			echo '</ul>';
103			++$j;
104		}
105		echo '</ul>',
106			'<p><input type="submit" name="Submit" value="', __('Display Checked'), '" /></p>',
107			'</form>';
108	}
109	
110	if (!isset($_GET['ViewTopic'])) {
111		$_GET['ViewTopic'] = '';
112	}
113	
114	foreach($TOC_Array['TableOfContents'] as $Name => $FullName) {
115		$PostName = 'Select' . $Name;
116		if (($_GET['ViewTopic'] == $Name) or (isset($_POST[$PostName]))) {
117			if ($Name == 'APIFunctions') {
118				$Name .= '.php';
119			} else {
120				$Name .= '.html';
121			}
122			$ManualPage = 'locale/' . $Language . '/Manual/Manual' . $Name;
123			if (!file_exists($ManualPage)) {// If locale topic page not exist, use topic page in doc/Manual.
124				$ManualPage = 'doc/Manual/Manual' . $Name;
125			}
126			echo '<div id="manualpage">';
127			include($ManualPage);
128			echo '</div>';
129		}
130	}
131	
132	// Output the footer part:
133	$ManualFooter = 'locale/' . $Language . '/Manual/ManualFooter.html';
134	if (file_exists($ManualFooter)) {// Use locale ManualHeader.html if exists. Each language can have its own page footer.
135		include($ManualFooter);
136	} else {// Default page footer:
137		echo '<div class="right">
138				<a id="bottom">&#160;</a><a class="minitext" href="#top">⬆ ', __('Go to Top'), '</a><br />
139				<a id="top">&#160;</a><a class="minitext" href="', htmlspecialchars($_SERVER['PHP_SELF'],ENT_QUOTES,'UTF-8'), '">☜ ', __('Table of Contents'), '</a>
140			</div>
141		</body>
142		</html>';
143	}
144	
145	ob_end_flush();
146

