29	function GetStockGLCode($StockID) {
30	
31		/*Gets the GL Codes relevant to the stock item account from the stock category record */
32		$QuerySQL = "SELECT stockact,
33							adjglact,
34							issueglact,
35							purchpricevaract,
36							materialuseagevarac,
37							wipact
38					FROM stockmaster
39					INNER JOIN stockcategory
40						ON stockmaster.categoryid=stockcategory.categoryid
41					WHERE stockmaster.stockid = '" . $StockID . "'";
42	
43		$ErrMsg = __('The stock GL codes could not be retrieved because');
44		$GetStkGLResult = DB_query($QuerySQL, $ErrMsg);
45	
46		$MyRow = DB_fetch_array($GetStkGLResult);
47		return $MyRow;
48	}
