72	function GetTaxes($TaxGroup, $DispatchTaxProvince, $TaxCategory) {
73	
74		$SQL = "SELECT taxgrouptaxes.calculationorder,
75						taxauthorities.description,
76						taxgrouptaxes.taxauthid,
77						taxauthorities.taxglcode,
78						taxgrouptaxes.taxontax,
79						taxauthrates.taxrate
80				FROM taxauthrates
81				INNER JOIN taxgrouptaxes
82					ON taxauthrates.taxauthority=taxgrouptaxes.taxauthid
83				INNER JOIN taxauthorities
84					ON taxauthrates.taxauthority=taxauthorities.taxid
85				WHERE taxgrouptaxes.taxgroupid='" . $TaxGroup . "'
86					AND taxauthrates.dispatchtaxprovince='" . $DispatchTaxProvince . "'
87					AND taxauthrates.taxcatid = '" . $TaxCategory . "'
88				ORDER BY taxgrouptaxes.calculationorder";
89	
90		$ErrMsg = __('The taxes and rate for this tax group could not be retrieved because');
91		$GetTaxesResult = DB_query($SQL, $ErrMsg);
92	
93		if (DB_num_rows($GetTaxesResult) >= 1) {
94			return $GetTaxesResult;
95		} else {
96			/*The tax group is not defined with rates */
97			return 0;
98		}
99	}
