101	function GetSalesGLCode($salesarea, $partnumber) {
102	    $SQL="SELECT salesglcode FROM salesglpostings
103				WHERE stkcat='any'";
104	    $Result = DB_query($SQL);
105	    $MyRow=DB_fetch_array($Result);
106	    return $MyRow[0];
