156	function ItemCostUpdateGL($StockID, $NewCost, $OldCost, $QOH) {
157	
158		if ($_SESSION['CompanyRecord']['gllink_stock'] == 1
159			AND $QOH != 0
160			AND (abs($NewCost - $OldCost) > pow(10, -($_SESSION['StandardCostDecimalPlaces'] + 1)))) {
161	
162			$CostUpdateNo = GetNextTransNo(35);
163			$PeriodNo = GetPeriod(date($_SESSION['DefaultDateFormat']));
164			$StockGLCode = GetStockGLCode($StockID);
165	
166			$ValueOfChange = $QOH * ($NewCost - $OldCost);
167	
168			$SQL = "INSERT INTO gltrans (type,
169										typeno,
170										trandate,
171										periodno,
172										account,
173										narrative,
174										amount)
175							VALUES ('35',
176							'" . $CostUpdateNo . "',
177							CURRENT_DATE,
178							'" . $PeriodNo . "',
179							'" . $StockGLCode['adjglact'] . "',
180							'" . mb_substr($StockID . ' ' . __('cost was') . ' ' . $OldCost . ' ' . __('changed to') . ' '
181								. $NewCost . ' x ' . __('Quantity on hand of') . ' ' . $QOH, 0, 200) . "',
182							'" . -$ValueOfChange . "')";
183	
184			$ErrMsg = __('CRITICAL ERROR') . '! ' . __('NOTE DOWN THIS ERROR AND SEEK ASSISTANCE') . ': '
185				. __('The GL credit for the stock cost adjustment posting could not be inserted because');
186			$Result = DB_query($SQL, $ErrMsg, '', true);
187	
188			$SQL = "INSERT INTO gltrans (type,
189							typeno,
190							trandate,
191							periodno,
192							account,
193							narrative,
194							amount)
195						VALUES ('35',
196							'" . $CostUpdateNo . "',
197							CURRENT_DATE,
198							'" . $PeriodNo . "',
199							'" . $StockGLCode['stockact'] . "',
200							'" . mb_substr($StockID . ' ' . __('cost was') . ' ' . $OldCost . ' ' . __('changed to') . ' '
201								. $NewCost . ' x ' . __('Quantity on hand of') . ' ' . $QOH, 0, 200) . "',
202							'" . $ValueOfChange . "')";
203	
204			$ErrMsg = __('CRITICAL ERROR') . '! ' . __('NOTE DOWN THIS ERROR AND SEEK ASSISTANCE') . ': '
205				. __('The GL debit for stock cost adjustment posting could not be inserted because');
206			$Result = DB_query($SQL, $ErrMsg, '', true);
207		}
208	}
