210	/* Calculates the material cost of a bill of materials, given parent code */
211	function BomMaterialCost($Parent) {
212		$SQL = "SELECT materialcost FROM stockmaster WHERE stockid='" . $Parent . "'";
213		$Result1 = DB_query($SQL);
214		$MyRow1 = DB_fetch_row($Result1);
215		$OldCost = $MyRow1[0];
216		$SQL = "SELECT sum(quantity) as qoh from locstock where stockid='" . $Parent . "'";
217		$Result1 = DB_query($SQL);
218		$MyRow1 = DB_fetch_row($Result1);
219		$QOH = $MyRow1[0];
220		$SQL = "SELECT SUM(stockmaster.actualcost * bom.quantity) AS SumOfmaterialcost
221				FROM bom
222				LEFT JOIN stockmaster
223					ON bom.component = stockmaster.stockid
224				WHERE bom.parent='". $Parent . "'
225					AND bom.effectiveafter <= CURRENT_DATE
226					AND bom.effectiveto > CURRENT_DATE";
227		$Result = DB_query($SQL);
228		$MyRow = DB_fetch_row($Result);
229		$MaterialCost = $MyRow[0];
230		if (abs($QOH*($MaterialCost-$OldCost))>0) {
231			ItemCostUpdateGL($Parent, $MaterialCost, $OldCost, $QOH);
232		}
233		return $MaterialCost;
234	}
