236	/* Iterates through the levels of the bom, recalculating each bom it meets */
237	function UpdateCost($Item) {
238		$SQL = "SELECT parent FROM bom where component = '" . $Item . "'";
239		$Result = DB_query($SQL);
240		while ($MyRow = DB_fetch_array($Result)) {
241			$NewParent = $MyRow['parent'];
242			$MaterialCost = BomMaterialCost($NewParent);
243			$SQL = "UPDATE stockmaster SET materialcost=" . $MaterialCost . " WHERE stockid='" . $NewParent . "'";
244			$Result1 = DB_query($SQL);
245			if (DB_error_no() != 0) {
246				return 1;
247			}
248			UpdateCost($NewParent);
249		}
250		return 0;
251	}
