253	/* Accepts work order information and iterates through the bom, inserting real components (dissolving phantom assemblies) */
254	function WoRealRequirements($WO, $LocCode, $StockID, $Qty = 1, $ParentID = '') {
255	
256		// remember, 'G' is for ghost (phantom part type)
257	
258		// all components should be referenced to the initial parent
259		if ($ParentID == '') {
260			$ParentID = $StockID;
261		}
262	
263		// insert new real immediate components of this item
264		$SQL = "INSERT INTO worequirements (wo,
265					parentstockid,
266					stockid,
267					qtypu,
268					stdcost,
269					autoissue)
270				SELECT '" . $WO . "',
271					'" . $ParentID . "',
272					bom.component,
273					bom.quantity * " . $Qty . ",
274					actualcost,
275					bom.autoissue
276				FROM bom
277				INNER JOIN stockmaster
278					ON bom.component=stockmaster.stockid
279				WHERE bom.parent='" . $StockID . "'
280					AND bom.loccode ='" . $LocCode . "'
281					AND bom.effectiveafter <= CURRENT_DATE
282					AND bom.effectiveto > CURRENT_DATE
283					AND stockmaster.mbflag <> 'G'
284					AND bom.component NOT IN (
285						SELECT stockid
286						FROM worequirements
287						WHERE wo = '" . $WO . "'
288						AND parentstockid = '" . $ParentID . "'
289					)";
290		$Result = DB_query($SQL);
291	
292		// combine real immediate components of this item with other occurrences in this work order
293		// otherwise, we could encounter a uniqueness violation:
294		//     - the same component could occur in multiple dissolved phantom assemblies
295		//     - need to sum quantities of multiple component occurrences
296		if ($ParentID != $StockID) {
297			$SQL = "UPDATE worequirements
298						INNER JOIN (
299							SELECT CAST('" . $WO . "' AS SIGNED) as wo,
300								CAST('NODE-1' AS CHAR) as parentstockid,
301								bom.component AS stockid,
302								bom.quantity*1 AS qtypu,
303								actualcost AS stdcost,
304								bom.autoissue
305							FROM bom
306							INNER JOIN stockmaster
307								ON bom.component=stockmaster.stockid
308							WHERE bom.parent='" . $StockID . "'
309								AND bom.loccode ='" . $LocCode . "'
310								AND bom.effectiveafter <= CURRENT_DATE
311								AND bom.effectiveto > CURRENT_DATE
312								AND stockmaster.mbflag <> 'G'
313								AND bom.component IN (
314									SELECT stockid
315									FROM worequirements
316									WHERE wo = '" . $WO . "'
317									AND parentstockid = '". $ParentID . "'
318								)
319						) AS g ON g.wo=worequirements.wo
320							AND g.parentstockid=worequirements.parentstockid
321							AND g.stockid=worequirements.stockid
322						SET worequirements.qtypu = worequirements.qtypu + g.qtypu";
323			$Result = DB_query($SQL);
324		}
325	
326		// dissolve phantom assemblies
327		$SQL = "SELECT
328					bom.component,
329					bom.quantity
330				FROM bom
331				INNER JOIN stockmaster
332					ON bom.component=stockmaster.stockid
333				WHERE parent='" . $StockID . "'
334					AND loccode ='" . $LocCode . "'
335					AND bom.effectiveafter <= CURRENT_DATE
336					AND bom.effectiveto > CURRENT_DATE
337					AND stockmaster.mbflag='G'";
338		$Result = DB_query($SQL);
339		while ($MyRow = DB_fetch_array($Result)) {
340			WoRealRequirements($WO, $LocCode, $MyRow['component'], $MyRow['quantity'], $ParentID);
341		}
342	}
