344	/*Ensures general ledger entries balance for a given transaction */
345	function EnsureGLEntriesBalance($TransType, $TransTypeNo) {
346	
347		$Result = DB_query("SELECT COALESCE(SUM(amount), 0)
348							FROM gltrans
349							WHERE type = '" . $TransType . "'
350								AND typeno = '" . $TransTypeNo . "'");
351		$MyRow = DB_fetch_row($Result);
352		$Difference = $MyRow[0];
353		if (abs($Difference) != 0) {
354			if (abs($Difference) > CurrencyTolerance($_SESSION['CompanyRecord']['currencydefault'])) {
355				prnMsg(__('The general ledger entries created do not balance. See your system administrator'), 'error');
356				DB_Txn_Rollback();
357			} else {
358				$Result = DB_query("SELECT counterindex,
359											MAX(amount)
360									FROM gltrans
361									WHERE type = '" . $TransType . "'
362										AND typeno = '" . $TransTypeNo . "'
363									GROUP BY counterindex");
364				$MyRow = DB_fetch_array($Result);
365				$TransToAmend = $MyRow['counterindex'];
366				$Result = DB_query("UPDATE gltrans
367									SET amount = amount - " . $Difference . "
368									WHERE counterindex = '" . $TransToAmend . "'");
369	
370			}
371		}
372	}
