450	function CurrencyTolerance($Currency = '') {
451		if (($Currency == $_SESSION['CompanyRecord']['currencydefault']) 
452			or ($Currency != '')) {
453			// it is the home currency
454			return pow(10, -$_SESSION['CompanyRecord']['decimalplaces']);
455		} else {
456			// it is a foreign currency so get its decimal places
457			$Result = DB_query("SELECT decimalplaces FROM currencies WHERE currency = '" . $Currency . "'");
458			$MyRow = DB_fetch_row($Result);
459			return pow(10, -$MyRow[0]);
460		}
461	}
