463	function AdjustBankAccountsDueToCurrencyExchangeRate($SelectedCurrency, $OldRate, $NewRate){
464		/* We should update the functional currency value of the bank accounts of the $SelectedCurrency
465		Example: if functional currency = IDR and we have a bank account in USD.
466		Before rate was 1 USD = 9.000 IDR so OldRate = 1 /9.000 = 0.000111
467		if the new exchange rate is 1 USD = 10.000 IDR NewRate will be 0.0001.
468		If we had 5.000 USD on the bank account, we had 45.000.000 IDR on the balance sheet.
469		After we update to the new rate, we still have 5.000 USD on the bank account
470		but the balance value of the bank account is 50.000.000 IDR, so let's adjust the value */
471	
472		/*Get the current period */
473		$PostingDate = date($_SESSION['DefaultDateFormat']);
474		$PeriodNo = GetPeriod($PostingDate);
475	
476		$ExDiffTransNo = GetNextTransNo(36);
477	
478		/* get all the bank accounts denominated on the selected currency */
479		$SQLBankAccounts = "SELECT 	bankaccountname,
480									accountcode
481							FROM bankaccounts
482							WHERE currcode = '" . $SelectedCurrency . "'";
483		$ResultBankAccounts = DB_query($SQLBankAccounts);
484		while ($MyRowBankAccount=DB_fetch_array($ResultBankAccounts)) {
485	
486			/*Get the balance of the bank account concerned */
487			$SQL = "SELECT SUM(amount) as balance
488					FROM gltotals
489					WHERE period<='" . $PeriodNo . "'
490					AND account='" . $MyRowBankAccount['accountcode'] . "'";
491	
492			$ErrMsg = __('The bank account balance could not be returned by the SQL because');
493			$BalanceResult = DB_query($SQL, $ErrMsg);
494			$MyRow = DB_fetch_row($BalanceResult);
495			$OldBalanceInFunctionalCurrency = $MyRow[0];
496			$BalanceInAccountCurrency = $OldBalanceInFunctionalCurrency * $OldRate;
497	
498			/* Now calculate the Balance in functional currency at the new rate */
499			$NewBalanceInFunctionalCurrency = $BalanceInAccountCurrency / $NewRate;
500	
501			/* If some adjustment has to be done, do it! */
502			$DifferenceToAdjust = $NewBalanceInFunctionalCurrency - $OldBalanceInFunctionalCurrency;
503			if ($OldRate !=  $NewRate) {
504	
505				$SQL = "INSERT INTO gltrans (
506								type,
507								typeno,
508								trandate,
509								periodno,
510								account,
511								narrative,
512								amount
513							) VALUES (
514								36, '" .
515								$ExDiffTransNo . "', '" .
516								FormatDateForSQL($PostingDate) . "', '" .
517								$PeriodNo . "', '" .
518								$_SESSION['CompanyRecord']['currencyexchangediffact'] . "', '" .
519								mb_substr($MyRowBankAccount['bankaccountname'] . ' ' . __('currency rate adjustment to') . ' ' . locale_number_format($NewRate, 'Variable') . ' ' . $SelectedCurrency . '/' . $_SESSION['CompanyRecord']['currencydefault'], 0, 200) . "', '" .
520								(-$DifferenceToAdjust) . "')";
521				$ErrMsg = __('Cannot insert a GL entry for the currency exchange difference because');
522				DB_query($SQL, $ErrMsg, '', true);
523				
524				$SQL = "INSERT INTO gltrans (
525								type,
526								typeno,
527								trandate,
528								periodno,
529								account,
530								narrative,
531								amount
532							) VALUES (36, '" .
533								$ExDiffTransNo . "', '" .
534								FormatDateForSQL($PostingDate) . "', '" .
535								$PeriodNo . "', '" .
536								$MyRowBankAccount['accountcode'] . "', '" .
537								mb_substr($MyRowBankAccount['bankaccountname'] . ' ' . __('currency rate adjustment to') . ' ' . locale_number_format($NewRate, 'Variable') . ' ' . $SelectedCurrency . '/' . $_SESSION['CompanyRecord']['currencydefault'], 0, 200) . "', '" .
538								($DifferenceToAdjust) . "')";
539	
540				DB_query($SQL, $ErrMsg, '', true);
541				prnMsg(__('Bank Account') . ' ' . $MyRowBankAccount['bankaccountname'] . ' ' . __('Currency Rate difference of') . ' ' . locale_number_format($DifferenceToAdjust, $_SESSION['CompanyRecord']['decimalplaces']) . ' ' . __('has been posted'),'success');
542			}
543		}
544	}

