4	
5	function CharacterSet($Table) {
6		$SQL = "SELECT TABLE_COLLATION
7			FROM information_schema.tables
8			WHERE TABLE_SCHEMA='" . $_SESSION['DatabaseName'] . "'
9				AND TABLE_NAME='" . $Table . "'";
10		$Result = DB_query($SQL);
11		$MyRow = DB_fetch_array($Result);
12		return $MyRow['TABLE_COLLATION'];
13	}
14	
15	function CreateTrigger($Table, $TriggerName, $Event, $Row, $EventSql) {
16		$SQL = "SELECT TRIGGER_NAME
17			FROM information_schema.triggers
18			WHERE TRIGGER_NAME='" . $TriggerName . "'
19			AND TRIGGER_SCHEMA='" . $_SESSION['DatabaseName'] . "'";
20		$Result = DB_query($SQL);
21		if (DB_num_rows($Result) == 0) {
22			$SQL = "CREATE TRIGGER " . $TriggerName . " " . $Event . " ON " . $Table . " FOR EACH ROW SET " . $Row . "." . $EventSql;
