1	<?php
2	
3	/* Creates sales invoices from entered sales orders based on the quantities dispatched that can be modified */
4	
5	// NB: these classes are not autoloaded, and their definition has to be included before the session is started (in session.php)
6	include('includes/DefineCartClass.php');
7	include('includes/DefineSerialItems.php');
8	
9	require(__DIR__ . '/includes/session.php');
10	
11	$Title = __('Confirm Dispatches and Invoice An Order');
12	$ViewTopic = 'ARTransactions';
13	$BookMark = 'ConfirmInvoice';
14	include('includes/header.php');
15	
16	include('includes/CurrenciesArray.php');
17	include('includes/SQL_CommonFunctions.php');
18	include('includes/FreightCalculation.php');
19	include('includes/GetSalesTransGLCodes.php');
20	include('includes/CommissionFunctions.php');
21	
22	if (empty($_GET['identifier'])) {
23		/*unique session identifier to ensure that there is no conflict with other order entry sessions on the same machine  */
24		$identifier = date('U');
25	} else {
26		$identifier = $_GET['identifier'];
27	}
28	
29	if (!isset($_GET['OrderNumber']) and !isset($_SESSION['ProcessingOrder'])) {
30		/* This page can only be called with an order number for invoicing*/
31		echo '<div class="centre">
32				<a href="' . $RootPath . '/SelectSalesOrder.php">' . __('Select a sales order to invoice') . '</a>
33			</div>
34			<br />';
35		prnMsg(__('This page can only be opened if an order has been selected Please select an order first from the delivery details screen click on Confirm for invoicing'), 'error');
36		include('includes/footer.php');
37		exit();
38	} elseif (isset($_GET['OrderNumber']) and $_GET['OrderNumber'] > 0) {
39	
40		unset($_SESSION['Items' . $identifier]->LineItems);
41		unset($_SESSION['Items' . $identifier]);
42	
43		$_SESSION['ProcessingOrder'] = (int)$_GET['OrderNumber'];
44		$_GET['OrderNumber'] = (int)$_GET['OrderNumber'];
45		$_SESSION['Items' . $identifier] = new Cart;
46	
47		/*read in all the guff from the selected order into the Items cart */
48	
49		$OrderHeaderSQL = "SELECT salesorders.orderno,
50									salesorders.debtorno,
51									debtorsmaster.name,
52									salesorders.branchcode,
53									salesorders.customerref,
54									salesorders.comments,
55									salesorders.internalcomment,
56									salesorders.orddate,
57									salesorders.ordertype,
58									salesorders.shipvia,
59									salesorders.deliverto,
60									salesorders.deladd1,
61									salesorders.deladd2,
62									salesorders.deladd3,
63									salesorders.deladd4,
64									salesorders.deladd5,
65									salesorders.deladd6,
66									salesorders.contactphone,
67									salesorders.contactemail,
68									salesorders.salesperson,
69									salesorders.freightcost,
70									salesorders.deliverydate,
71									debtorsmaster.currcode,
72									salesorders.fromstkloc,
73									locations.taxprovinceid,
74									custbranch.taxgroupid,
75									currencies.rate as currency_rate,
76									currencies.decimalplaces,
77									custbranch.defaultshipvia,
78									custbranch.specialinstructions,
79									pickreq.consignment,
80									pickreq.packages
81							FROM salesorders
82							INNER JOIN debtorsmaster
83								ON salesorders.debtorno = debtorsmaster.debtorno
84							INNER JOIN custbranch
85								ON salesorders.branchcode = custbranch.branchcode
86								AND salesorders.debtorno = custbranch.debtorno
87							INNER JOIN currencies
88								ON debtorsmaster.currcode = currencies.currabrev
89							INNER JOIN locations
90								ON locations.loccode=salesorders.fromstkloc
91							INNER JOIN locationusers
92								ON locationusers.loccode=salesorders.fromstkloc
93								AND locationusers.userid='" . $_SESSION['UserID'] . "'
94								AND locationusers.canupd=1
95							LEFT OUTER JOIN pickreq
96								ON pickreq.orderno=salesorders.orderno
97								AND pickreq.closed=0
98							WHERE salesorders.orderno = '" . $_GET['OrderNumber'] . "'";
99	
100		if ($_SESSION['SalesmanLogin'] != '') {
101			$OrderHeaderSQL.= " AND salesorders.salesperson='" . $_SESSION['SalesmanLogin'] . "'";
102		}
103	
104		$ErrMsg = __('The order cannot be retrieved because');
105		$GetOrdHdrResult = DB_query($OrderHeaderSQL, $ErrMsg);
106	
107		if (DB_num_rows($GetOrdHdrResult) == 1) {
108	
109			$MyRow = DB_fetch_array($GetOrdHdrResult);
110	
111			$_SESSION['Items' . $identifier]->DebtorNo = $MyRow['debtorno'];
112			$_SESSION['Items' . $identifier]->OrderNo = $MyRow['orderno'];
113			$_SESSION['Items' . $identifier]->Branch = $MyRow['branchcode'];
114			$_SESSION['Items' . $identifier]->CustomerName = $MyRow['name'];
115			$_SESSION['Items' . $identifier]->CustRef = $MyRow['customerref'];
116			$_SESSION['Items' . $identifier]->Comments = $MyRow['comments'];
117			$_SESSION['Items' . $identifier]->DefaultSalesType = $MyRow['ordertype'];
118			$_SESSION['Items' . $identifier]->DefaultCurrency = $MyRow['currcode'];
119			$_SESSION['Items' . $identifier]->CurrDecimalPlaces = $MyRow['decimalplaces'];
120			$BestShipper = $MyRow['shipvia'];
121			$_SESSION['Items' . $identifier]->ShipVia = $MyRow['shipvia'];
122			$_SESSION['Items' . $identifier]->InternalComments = reverse_escape($MyRow['internalcomment']);
123			$_SESSION['Items' . $identifier]->Consignment = $MyRow['consignment'];
124			$_SESSION['Items' . $identifier]->Packages = $MyRow['packages'];
125	
126			if (is_null($BestShipper)) {
127				$BestShipper = 0;
128			}
129			$_SESSION['Items' . $identifier]->DeliverTo = $MyRow['deliverto'];
130			$_SESSION['Items' . $identifier]->DeliveryDate = ConvertSQLDate($MyRow['deliverydate']);

600	} else {
601		$DefaultDispatchDate = $_POST['DispatchDate'];
602	}
603	
604	echo '<tbody></table><br />';
605	
606	if (isset($_POST['ProcessInvoice']) and $_POST['ProcessInvoice'] != '') {
607	
608		/* SQL to process the postings for sales invoices...
609	
610		/*First check there are lines on the dipatch with quantities to invoice
611		invoices can have a zero amount but there must be a quantity to invoice */
612	
613		$QuantityInvoicedIsPositive = false;
614	
615		foreach ($_SESSION['Items' . $identifier]->LineItems as $OrderLine) {
616			if ($OrderLine->QtyDispatched > 0) {
617				$QuantityInvoicedIsPositive = true;
618			}
619		}
620		if (!$QuantityInvoicedIsPositive) {
621			prnMsg(__('There are no lines on this order with a quantity to invoice') . '. ' . __('No further processing has been done'), 'error');
622			include('includes/footer.php');
623			exit();
624		}
625	
626		if ($_SESSION['ProhibitNegativeStock'] == 1) { // checks for negative stock after processing invoice
627			//sadly this check does not combine quantities occuring twice on and order and each line is considered individually :-(
628			$NegativesFound = false;
629			foreach ($_SESSION['Items' . $identifier]->LineItems as $OrderLine) {
630				$SQL = "SELECT stockmaster.description,
631								locstock.quantity,
632						 		stockmaster.mbflag
633			 			FROM locstock
634			 			INNER JOIN stockmaster
635						ON stockmaster.stockid=locstock.stockid
636						WHERE stockmaster.stockid='" . $OrderLine->StockID . "'
637						AND locstock.loccode='" . $_SESSION['Items' . $identifier]->Location . "'";
638	
639				$ErrMsg = __('Could not retrieve the quantity left at the location once this order is invoiced (for the purposes of checking that stock will not go negative because)');
640				$Result = DB_query($SQL, $ErrMsg);
641				$CheckNegRow = DB_fetch_array($Result);
642				if (($CheckNegRow['mbflag'] == 'B' or $CheckNegRow['mbflag'] == 'M') and mb_substr($OrderLine->StockID, 0, 4) != 'ASSET') {
643					if ($CheckNegRow['quantity'] < $OrderLine->QtyDispatched) {
644						prnMsg(__('Invoicing the selected order would result in negative stock. The system parameters are set to prohibit negative stocks from occurring. This invoice cannot be created until the stock on hand is corrected.'), 'error', $OrderLine->StockID . ' ' . $CheckNegRow['description'] . ' - ' . __('Negative Stock Prohibited'));
645						$NegativesFound = true;
646					}
647				} elseif ($CheckNegRow['mbflag'] == 'A') {
648	
649					/*Now look for assembly components that would go negative */
650					$SQL = "SELECT bom.component,
651								stockmaster.description,
652								locstock.quantity-(" . $OrderLine->QtyDispatched . "*bom.quantity) AS qtyleft
