412	/* Applies credit control to an order that has just been entered or changed, by any route (BR-06, BR-10):
413	 * - orders for customers on stop are put on hold
414	 * - with CheckCreditLimits = 3 orders that take the customer over their credit limit are put on hold
415	 * $PreviousValue is the value of the order before a modification - an order that has not grown is not re-checked
416	 * against the limit, so that credit control's release is not undone by changing a delivery address.
417	 * Returns the hold status of the order. */
418	function ApplyOrderCreditHold($OrderNo, $DebtorNo, $PreviousValue = null) {
419		$Result = DB_query("SELECT quotation, credithold FROM salesorders WHERE orderno='" . $OrderNo . "'");
420		$Order = DB_fetch_array($Result);
421		if ($Order['quotation'] != 0) {
422			return 0;
423		}
424		$NewHold = 0;
425		if (CustomerOnStop($DebtorNo)) {
426			$NewHold = 1;
427		} elseif (CreditControlConfig('CheckCreditLimits', 0) == 3
428			and ($PreviousValue === null or GetOrderOutstandingValue($OrderNo) > $PreviousValue + 0.005)) {
429			/* GetCreditAvailable already takes this order into account as it is now in the database */
430			if (GetCreditAvailable($DebtorNo) < 0) {
431				$NewHold = 2;
432			}
433		}
434		if ($NewHold != 0 and $NewHold != $Order['credithold']) {
435			$ErrMsg = __('The order could not be put on credit hold because');
436			DB_query("UPDATE salesorders SET credithold='" . $NewHold . "' WHERE orderno='" . $OrderNo . "'", $ErrMsg, '', true);
437			LogCreditControlEvent($DebtorNo, 'OrderHold', CreditHoldDescription($NewHold), '', CreditHoldDescription($NewHold), 0, 0, $OrderNo);
438			return $NewHold;
439		}

